if(!$mother || ($role===3 && (int)$mother['chw_id']!==(int)$_SESSION['u_id']) || (in_array($role,[2,4],true) && (empty($_SESSION['facility_id']) || (int)$mother['facility_id']!==(int)$_SESSION['facility_id']))){http_response_code(404);exit('Mother record not found.');}
$err='';$msg='';
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['save_history'])){
 if(!in_array($role,[1,2,3],true)){http_response_code(403);exit('Not authorized.');}
 try{$p=(int)$_POST['pregnancy_id'];$valid=$db->prepare("SELECT pregnancy_id FROM tbl_pregnancies WHERE pregnancy_id=? AND mother_id=?");$valid->execute([$p,$id]);if(!$valid->fetchColumn())throw new RuntimeException('Choose a pregnancy for this mother.');
 $sql="INSERT INTO tbl_maternal_history(mother_id,pregnancy_id,previous_preeclampsia,chronic_hypertension,diabetes,kidney_disease,multiple_pregnancy,previous_stillbirth,previous_severe_complication,medical_history,obstetric_history,recorded_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE previous_preeclampsia=VALUES(previous_preeclampsia),chronic_hypertension=VALUES(chronic_hypertension),diabetes=VALUES(diabetes),kidney_disease=VALUES(kidney_disease),multiple_pregnancy=VALUES(multiple_pregnancy),previous_stillbirth=VALUES(previous_stillbirth),previous_severe_complication=VALUES(previous_severe_complication),medical_history=VALUES(medical_history),obstetric_history=VALUES(obstetric_history),recorded_by=VALUES(recorded_by)";
 $db->prepare($sql)->execute([$id,$p,isset($_POST['previous_preeclampsia']),isset($_POST['chronic_hypertension']),isset($_POST['diabetes']),isset($_POST['kidney_disease']),isset($_POST['multiple_pregnancy']),isset($_POST['previous_stillbirth']),isset($_POST['previous_severe_complication']),trim($_POST['medical_history']),trim($_POST['obstetric_history']),$_SESSION['u_id']]);
 audit_log($db,$_SESSION['u_id'],'SAVE_MATERNAL_HISTORY','tbl_maternal_history',$p);$msg='History saved for clinician review.';
 }catch(Throwable $e){$err=$e instanceof RuntimeException?$e->getMessage():'Unable to save history.';error_log($e->getMessage());}
}
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['review_history']) && in_array($role,[1,2],true)){$p=(int)$_POST['pregnancy_id'];$db->prepare('UPDATE tbl_maternal_history SET reviewed_by=?,reviewed_at=NOW() WHERE pregnancy_id=? AND mother_id=?')->execute([$_SESSION['u_id'],$p,$id]);audit_log($db,$_SESSION['u_id'],'REVIEW_MATERNAL_HISTORY','tbl_maternal_history',$p);$msg='History review recorded.';}
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['save_call_consent'])){
 if(!in_array($role,[1,2,3],true)){http_response_code(403);exit('Not authorized to manage call consent.');}
 try{
  $status=(string)($_POST['call_consent_status']??'');$source=trim((string)($_POST['call_consent_source']??''));
  if(!in_array($status,['granted','withdrawn'],true))throw new RuntimeException('Choose granted or withdrawn.');
  if($source===''||mb_strlen($source)>255)throw new RuntimeException('Record where the consent or withdrawal was documented (1–255 characters).');
  $db->beginTransaction();$motherLock=$db->prepare('SELECT mother_id FROM tbl_mothers WHERE mother_id=? FOR UPDATE');$motherLock->execute([$id]);if(!$motherLock->fetchColumn())throw new RuntimeException('Mother record not found.');
  $stmt=$db->prepare("INSERT INTO mcare_call_consent(mother_id,consent_status,consent_source,consented_at,withdrawn_at,recorded_by) VALUES(?,?,?,IF(?='granted',NOW(),NULL),IF(?='withdrawn',NOW(),NULL),?) ON DUPLICATE KEY UPDATE consent_status=VALUES(consent_status),consent_source=VALUES(consent_source),consented_at=IF(VALUES(consent_status)='granted',NOW(),consented_at),withdrawn_at=IF(VALUES(consent_status)='withdrawn',NOW(),NULL),recorded_by=VALUES(recorded_by)");
  $stmt->execute([$id,$status,$source,$status,$status,(int)$_SESSION['u_id']]);
  $activeChannels=[];if($status==='withdrawn'){$db->prepare("UPDATE mcare_outbound_calls SET status='cancelled',ended_at=NOW(),failure_reason='Automated-call consent withdrawn' WHERE mother_id=? AND status IN ('queued','pending')")->execute([$id]);$aq=$db->prepare("SELECT call_id,asterisk_channel FROM mcare_outbound_calls WHERE mother_id=? AND status IN ('initiating','ringing','answered','in_progress')");$aq->execute([$id]);$activeChannels=$aq->fetchAll(PDO::FETCH_ASSOC);}
  audit_log($db,(int)$_SESSION['u_id'],'AUTOMATED_CALL_CONSENT','mcare_call_consent',$id,null,['status'=>$status]);
  $db->commit();
  if($status==='withdrawn'&&$activeChannels){require_once __DIR__.'/inc/asterisk_ami.php';foreach($activeChannels as $activeCall){if(empty($activeCall['asterisk_channel']))continue;try{mcare_ami_hangup(mcare_ami_settings(),(string)$activeCall['asterisk_channel'],'mcare-optout-'.bin2hex(random_bytes(10)));$db->prepare("UPDATE mcare_outbound_calls SET status='cancelled',ended_at=NOW(),failure_reason='Automated-call consent withdrawn' WHERE call_id=? AND status IN ('initiating','ringing','answered','in_progress')")->execute([(int)$activeCall['call_id']]);$db->prepare("INSERT INTO mcare_outbound_call_events(call_id,event_type,event_detail) VALUES(?,'cancelled','Active call ended after automated-call consent withdrawal')")->execute([(int)$activeCall['call_id']]);}catch(Throwable $hangupError){error_log('Could not hang up call after consent withdrawal: '.$hangupError->getMessage());$err='Consent was withdrawn, but an active call could not be ended automatically. Hang up the channel in Asterisk immediately.';}}}
  $msg=$status==='granted'?'Automated-call consent recorded.':'Automated calls withdrawn; no new calls can be placed.';
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();$err=$e instanceof RuntimeException?$e->getMessage():'Could not update automated-call consent.';if(!($e instanceof RuntimeException))error_log('M-CARE call consent error: '.$e->getMessage());}
}
$callConsent=['consent_status'=>'not_recorded','consent_source'=>null,'consented_at'=>null,'withdrawn_at'=>null];$callConsentAvailable=true;
try{$cq=$db->prepare('SELECT consent_status,consent_source,consented_at,withdrawn_at FROM mcare_call_consent WHERE mother_id=?');$cq->execute([$id]);$callConsent=array_merge($callConsent,$cq->fetch(PDO::FETCH_ASSOC)?:[]);}catch(Throwable $e){$callConsentAvailable=false;}
$s=$db->prepare("SELECT p.*,FLOOR((CASE WHEN p.lmp IS NOT NULL THEN DATEDIFF(CURDATE(),p.lmp) WHEN p.ultrasound_edd IS NOT NULL THEN 280-DATEDIFF(p.ultrasound_edd,CURDATE()) ELSE NULL END)/7) ga_weeks,MOD(CASE WHEN p.lmp IS NOT NULL THEN DATEDIFF(CURDATE(),p.lmp) WHEN p.ultrasound_edd IS NOT NULL THEN 280-DATEDIFF(p.ultrasound_edd,CURDATE()) ELSE NULL END,7) ga_days,h.* FROM tbl_pregnancies p LEFT JOIN tbl_maternal_history h ON h.pregnancy_id=p.pregnancy_id WHERE p.mother_id=? ORDER BY p.created_at DESC");$s->execute([$id]);$pregnancies=$s->fetchAll(PDO::FETCH_ASSOC);
$s=$db->prepare("SELECT a.*,CONCAT(u.f_name,' ',u.l_name) recorder FROM tbl_anc_visits a LEFT JOIN tbl_users u ON u.u_id=a.recorded_by WHERE a.mother_id=? ORDER BY a.visit_date DESC");$s->execute([$id]);$anc=$s->fetchAll(PDO::FETCH_ASSOC);
$s=$db->prepare("SELECT a.*,r.report_date,r.symptoms_json FROM tbl_alerts a LEFT JOIN tbl_symptom_reports r ON r.report_id=a.report_id WHERE a.mother_id=? ORDER BY a.created_at DESC LIMIT 10");$s->execute([$id]);$alerts=$s->fetchAll(PDO::FETCH_ASSOC);
$s=$db->prepare("SELECT r.*,f.facility_name FROM tbl_referrals r LEFT JOIN tbl_facilities f ON f.facility_id=r.referred_to_facility WHERE r.mother_id=? ORDER BY r.referral_date DESC LIMIT 10");$s->execute([$id]);$referrals=$s->fetchAll(PDO::FETCH_ASSOC);
